"use server";

// Generated by philote from page /projects/new. Do not edit.
import { redirect } from "next/navigation";

import { projects } from "@/lib/api";
import { type FormState, failed, text } from "@/lib/form";

export async function submit(_state: FormState, data: FormData): Promise<FormState> {
    const result = await projects.create({
        name: text(data, "name"),
        summary: text(data, "summary"),
    });
    if (!result.ok) {
        return failed(data, result.error, result.issues);
    }
    redirect(`/projects/${encodeURIComponent(result.value.id)}`);
}
